head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDSTF41610.xml";
scwin.vSecugrpID = "";
scwin.list_dtl_noti_id;
scwin.belongDepCd = js_belngdepcd;
scwin.selBzProcsNo, scwin.selPrtDepoId, scwin.selExerSeq, scwin.selRowPos, scwin.isGongsi = "";
scwin.vIsurCd, scwin.vComNm = "";
scwin.clickBzProcsNo, scwin.clickListProcsStatCd = "";
scwin.clickIsurCd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
};
scwin.fn_list_sync = function() {
    /*	
		// 회사 선택
		if (txb_ISUR_CD.value == "") {
			alert("[회사]를 선택해주세요.");
			txb_ISUR_CD.focus();
			return;
		}
*/
    var ISUR_CD = txb_ISUR_CD.getValue();
    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=SKIL_GROWTH_COM_PIPELINE_PROG_LIST_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.skilgrowthcom.pipelineprog.select.list" + "&{P}V_ISUR_CD=" + ISUR_CD + "&{P}V_SLIST_DD=" + $c.stf.getObjectValue(edt_SDate) + "&{P}V_ELIST_DD=" + $c.stf.getObjectValue(edt_EDate);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


//2010.04.20 회사코드 추가
scwin.fn_SetPar = function(arrPar) {
    txb_COM_NM.setValue(arrPar[0].COM_NM);
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
};
scwin.fn_setBzProcsNo = function(obj) {
    scwin.clickIsurCd = dts_List.getCellData(eval(obj), "ISUR_CD");
    scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "PIPE_BZ_PROCS_NO");
    scwin.clickListProcsStatCd = dts_List.getCellData(eval(obj), "PIPE_LIST_PROCS_STAT_CD");
};
scwin.fn_setRcvRetButtonFalse = function() {
    $c.stf.showObj(btn_Acpt, false);
    $c.stf.showObj(btn_Ret, false);
};
scwin.fn_Receive = function(type) {
    var typeString = "";
    if (type == "33") typeString = "접수";

    else typeString = "반려";
    var vAnswer = confirm("선택된 항목을 모두 " + typeString + "처리 하시겠습니까?");
    if (vAnswer) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
        trs_Save.Action = $c.lc.fn_encodeNSession("/SkilGrowthComAFListOutcome.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=processPipelineProg");
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
        trs_Save.Parameters = "TRS_IDX=U" + ", LIST_BZ_TP_CD=800" + ", LIST_PROCS_STAT_CD=" + type + ", PIPE_BZ_PROCS_NO=" + scwin.clickBzProcsNo + ", PIPE_ISUR_CD=" + scwin.clickIsurCd + ",PROCS_EMP_NO=" + js_emp_no;
        trs_Save.Post();
    }
};
scwin.btn_select_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewOffice(grd_Grid, "파이프라인 진행 경과", "", 1, 0);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //txb_TotCnt.value = "총 " + rowcount + "건";						 
    if (rowcount <= 0) {
        dts_List.removeAll();
    }
    scwin.fn_setRcvRetButtonFalse(); // 접수,반려 버튼 안보이게
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (row > 0) {
        //그리드에서 선택시
        scwin.fn_setBzProcsNo(row);
    }
    if ("34" == scwin.clickListProcsStatCd) {
        //수정요청 리스트 팝업창
        var adjreqUrl = "/lstmgt/ULDSTF41611.gfm";
        await $c.frame.CreateDialogFrame("ULDSTF41611.gfm", adjreqUrl, "기술성장기업 상장이후 성과분석 수정요청 리스트", 50, 50, 750, 300, "window");
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(__GROUPBOX_BACKGROUND__panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    $c.stf.showObj(btn_Acpt, false);
    $c.stf.showObj(btn_Ret, false);
    scwin.fn_list_sync();
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_Acpt_onclick = function() {
    scwin.fn_Receive("33");
};
scwin.btn_Ret_onclick = function() {
    scwin.fn_Receive("37");
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S1');
    scwin.fn_list_sync();
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.grd_Grid_OnClick = function(row, colid) {
    //alert('grd_Grid.OnClick('+row+','+ colid+')');
    // 처리상태 제출완료 인 경우 접수, 반려 버튼 활성
    if (row > 0) {
        //그리드에서 선택시
        scwin.fn_setBzProcsNo(row);
    }
    if ("32" == scwin.clickListProcsStatCd) {
        //접수,반려 버튼 활성화
        $c.stf.showObj(btn_Acpt, true);
        $c.stf.showObj(btn_Ret, true);
        //btn_Acpt.disabled = false;
        //btn_Ret.disabled = false;

    } else {
        $c.stf.showObj(btn_Acpt, false);
        $c.stf.showObj(btn_Ret, false);
        //btn_Acpt.disabled = true;
        //btn_Ret.disabled = true;

    }
};
